class _KLangBundledLoader(_klang_importlib_abc.Loader):
    def create_module(self, spec):
        return None

    def exec_module(self, module):
        source = _KLANG_MODULE_SOURCES[module.__name__]
        module.__file__ = "<bundled " + module.__name__ + ">"
        if module.__name__ == "klang":
            module.__path__ = []
        exec(compile(source, module.__file__, "exec"), module.__dict__, module.__dict__)


class _KLangBundledFinder(_klang_importlib_abc.MetaPathFinder):
    _loader = _KLangBundledLoader()

    def find_spec(self, fullname, path=None, target=None):
        del path, target
        if fullname not in _KLANG_MODULE_SOURCES:
            return None
        return _klang_importlib_util.spec_from_loader(
            fullname, self._loader, is_package=fullname == "klang"
        )


_klang_sys.meta_path.insert(0, _KLangBundledFinder())
from klang.cli import main as _klang_cli_main


def main(argv=None):
    # Preserve the browser worker's historical argv contract. The authoritative
    # Python CLI accepts argument values without argv[0].
    if argv and argv[0] == "klang-browser":
        argv = argv[1:]
    return _klang_cli_main(argv)


if __name__ == "__main__":
    raise SystemExit(main())
